\question{7}{8} The following shows a sequence of figures formed by dots. The $n$th figure has $\dfrac{n(n+1)}{2}$ dots.

\par\vspace{0.5em}
\noindent\hspace*{2em}%
\begin{tikzpicture}[scale=0.42,baseline=-0.8ex,every node/.style={font=\small},dot/.style={circle,fill,inner sep=1.2pt}]
  \foreach \f/\x/\n in {1/0/1, 2/2.0/2, 3/4.8/3, 4/8.5/4} {
    \foreach \row in {1,...,\n} {
      \foreach \col in {1,...,\row} {
        \node[dot] at (\x+(\col-1)*0.55,-(\row-1)*0.55) {};
      }
    }
    \ifnum\f=1 \def\flabel{1st}\fi
    \ifnum\f=2 \def\flabel{2nd}\fi
    \ifnum\f=3 \def\flabel{3rd}\fi
    \ifnum\f=4 \def\flabel{4th}\fi
    \node[below] at (\x+(\n-1)*0.55/2,-(\n-1)*0.55-0.45) {\flabel};
  }
\end{tikzpicture}

\begin{subparts}
  \item Find the number of dots in the 15th figure.
  \item Can a figure in the sequence have $224$ dots? Explain your answer.
  \item Is the number of dots in the 11th figure odd? Explain your answer.
\end{subparts}

\answerlines{16}

\msquestion{7}{8}
\begin{mspart}{(a)}
  \msstep{\text{Number of dots in the 15th figure}=\dfrac{15\times 16}{2}=120}{2A}
\end{mspart}
\begin{mspart}{(b)}
  \msstep{\dfrac{n(n+1)}{2}=224}{1M}
  \msstep{n(n+1)=448}{1M}
  \msstep{20\times 21=420,\ 21\times 22=462}{1M}
  \msstep{\text{No, since 448 is not the product of two consecutive integers.}}{1A}
\end{mspart}
\begin{mspart}{(c)}
  \msstep{\text{Number of dots in the 11th figure}=\dfrac{11\times 12}{2}=66}{1M}
  \msstep{\text{66 is even, so disagree.}}{1A}
\end{mspart}

